import { execution } from '@dynatrace-sdk/automation-utils';

export default async function ({ executionId }) {
  const ex = await execution(executionId);
  const ev = ex.event() || {};

  const title =
    ev["event.name"] ||
    ev["problem.title"] ||
    ev.title ||
    "Dynatrace Problem";
  const problemId =
    ev["display_id"] ||
    ev["problem.id"] ||
    ev["event.id"] ||
    ev.pid ||
    "unknown-problem";
  const problemUrl =
    ev["problem.url"] ||
    ev["event.url"] ||
    ev.url ||
    "";
  const severity = String(
    ev["problem.severity"] ||
      ev["event.severity"] ||
      ev.severity ||
      "ERROR"
  ).toUpperCase();

  const tags = ev["entity_tags"] || ev.tags || [];
  const tagList = Array.isArray(tags) ? tags : [tags];

  function tagValue(key) {
    for (const t of tagList) {
      const s = String(t);
      if (s.startsWith(key + ":")) return s.slice(key.length + 1);
      if (typeof t === "object" && t && t.key === key) return t.value;
    }
    return null;
  }

  const app = tagValue("app") || tagValue("AGO_GLOBAL_APP") || "unknown-app";

  // EDIT these maps for your org (names shown in tickets; use sys_ids in SNOW body)
  const assignMap = {
    EIP: {
      groupName: "EIP-Support",
      groupSysId: "__SNOW_GROUP_SYS_ID_EIP__",
      bizName: "EIP Checkout",
      bizSysId: "__SNOW_BIZ_SYS_ID_EIP__",
      l1: "EIP-L1",
      l2: "EIP-L2",
      l3: "EIP-L3",
      runbook: "https://confluence.example/runbooks/eip"
    },
    CCI: {
      groupName: "CCI-Support",
      groupSysId: "__SNOW_GROUP_SYS_ID_CCI__",
      bizName: "CCI FA Comm Calc",
      bizSysId: "__SNOW_BIZ_SYS_ID_CCI__",
      l1: "CCI-L1",
      l2: "CCI-L2",
      l3: "CCI-L3",
      runbook: "https://confluence.example/runbooks/cci"
    },
    default: {
      groupName: "Ops-Default",
      groupSysId: "__SNOW_GROUP_SYS_ID_DEFAULT__",
      bizName: "Unknown Business Service",
      bizSysId: "__SNOW_BIZ_SYS_ID_DEFAULT__",
      l1: "Ops-L1",
      l2: "Ops-L2",
      l3: "Ops-L3",
      runbook: "https://confluence.example/runbooks/default"
    }
  };
  const meta = assignMap[app] || assignMap.default;

  let impact = "3";
  let urgency = "3";
  let pLevel = "P4";
  let pdSeverity = "warning";
  if (severity.includes("AVAILABILITY") || severity.includes("CRITICAL")) {
    impact = "2";
    urgency = "2";
    pLevel = "P3";
    pdSeverity = "critical";
  } else if (severity.includes("ERROR")) {
    impact = "2";
    urgency = "3";
    pLevel = "P3";
    pdSeverity = "error";
  }

  const description = [
    "Caller: Dynatrace Workflow (auto)",
    "Business service: " + meta.bizName,
    "App: " + app,
    "Priority intent: " + pLevel + " (impact=" + impact + ", urgency=" + urgency + ")",
    "",
    "Dynatrace Problem: " + problemUrl,
    "Problem ID: " + problemId,
    "",
    "Who can help:",
    "- L1: " + meta.l1,
    "- L2: " + meta.l2,
    "- L3: " + meta.l3,
    "",
    "Runbook / SOP: " + meta.runbook
  ].join("\n");

  return {
    caller: "Dynatrace Workflow",
    callerSysId: "__SNOW_CALLER_SYS_ID__",
    app,
    businessServiceName: meta.bizName,
    businessServiceSysId: meta.bizSysId,
    assignmentGroupName: meta.groupName,
    assignmentGroupSysId: meta.groupSysId,
    impact,
    urgency,
    pLevel,
    l1: meta.l1,
    l2: meta.l2,
    l3: meta.l3,
    runbookUrl: meta.runbook,
    problemId,
    problemUrl,
    problemTitle: title,
    pdSeverity,
    dedupKey: "dt-problem-" + problemId,
    shortDescription: "[Dynatrace] " + title + " — " + app,
    description,
    category: "Software",
    subcategory: "Application"
  };
}

import { execution } from '@dynatrace-sdk/automation-utils';

export default async function ({ executionId }) {
  const ex = await execution(executionId);
  const p = await ex.result("prepare-payload");

  // REPLACE placeholders or switch this task to ServiceNow Connector "Create Incident" in UI
  const snowBase = "__SNOW_INSTANCE_URL__"; // e.g. https://example.service-now.com
  const snowUser = "__SNOW_USER__";
  const snowPass = "__SNOW_PASSWORD__";
  const auth = btoa(snowUser + ":" + snowPass);

  const body = {
    correlation_id: p.problemId,
    caller_id: p.callerSysId,
    category: p.category,
    subcategory: p.subcategory,
    impact: p.impact,
    urgency: p.urgency,
    assignment_group: p.assignmentGroupSysId,
    business_service: p.businessServiceSysId,
    short_description: p.shortDescription,
    description: p.description
  };

  const res = await fetch(snowBase.replace(/\/$/, "") + "/api/now/v2/table/incident", {
    method: "POST",
    headers: {
      Authorization: "Basic " + auth,
      "Content-Type": "application/json",
      Accept: "application/json"
    },
    body: JSON.stringify(body)
  });

  const text = await res.text();
  let json = {};
  try { json = JSON.parse(text); } catch (e) { json = { raw: text }; }
  if (!res.ok) {
    throw new Error("ServiceNow create failed HTTP " + res.status + ": " + text);
  }

  const result = json.result || json;
  return {
    sysId: result.sys_id,
    number: result.number,
    raw: result
  };
}

import { execution } from '@dynatrace-sdk/automation-utils';

export default async function ({ executionId }) {
  const ex = await execution(executionId);
  const p = await ex.result("prepare-payload");

  const routingKey = "__PD_ROUTING_KEY__"; // 32-char Events API v2 integration key

  const body = {
    routing_key: routingKey,
    event_action: "trigger",
    dedup_key: p.dedupKey,
    client: "Dynatrace",
    client_url: p.problemUrl,
    links: [
      { href: p.problemUrl, text: "Open Dynatrace Problem" },
      { href: p.runbookUrl, text: "Runbook" }
    ],
    payload: {
      summary: p.shortDescription,
      source: p.app,
      severity: p.pdSeverity,
      component: p.app,
      group: p.assignmentGroupName,
      class: "dynatrace-problem",
      custom_details: {
        problem_id: p.problemId,
        problem_url: p.problemUrl,
        business_service: p.businessServiceName,
        assignment_group: p.assignmentGroupName,
        priority_intent: p.pLevel,
        l1: p.l1,
        l2: p.l2,
        l3: p.l3,
        runbook: p.runbookUrl,
        caller: p.caller
      }
    }
  };

  const res = await fetch("https://events.pagerduty.com/v2/enqueue", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(body)
  });
  const text = await res.text();
  let json = {};
  try { json = JSON.parse(text); } catch (e) { json = { raw: text }; }
  if (!res.ok) {
    throw new Error("PagerDuty trigger failed HTTP " + res.status + ": " + text);
  }
  return {
    status: json.status,
    dedupKey: json.dedup_key || p.dedupKey,
    message: json.message,
    raw: json
  };
}

import { execution } from '@dynatrace-sdk/automation-utils';

export default async function ({ executionId }) {
  const ex = await execution(executionId);
  const snow = await ex.result("create-servicenow-incident");
  const pd = await ex.result("create-pagerduty-incident");
  const p = await ex.result("prepare-payload");

  const snowBase = "__SNOW_INSTANCE_URL__";
  const snowUser = "__SNOW_USER__";
  const snowPass = "__SNOW_PASSWORD__";
  const auth = btoa(snowUser + ":" + snowPass);

  const comment =
    "PagerDuty sync: dedup_key=" + pd.dedupKey +
    " | Dynatrace Problem=" + p.problemUrl +
    " | Runbook=" + p.runbookUrl;

  const res = await fetch(
    snowBase.replace(/\/$/, "") + "/api/now/v2/table/incident/" + snow.sysId,
    {
      method: "PATCH",
      headers: {
        Authorization: "Basic " + auth,
        "Content-Type": "application/json",
        Accept: "application/json"
      },
      body: JSON.stringify({ work_notes: comment })
    }
  );
  const text = await res.text();
  if (!res.ok) {
    throw new Error("ServiceNow comment failed HTTP " + res.status + ": " + text);
  }
  return {
    incidentNumber: snow.number,
    incidentSysId: snow.sysId,
    pagerDutyDedupKey: pd.dedupKey,
    problemId: p.problemId
  };
}
